import ipaddress as ip
nets = {"onprem": "10.10.0.0/16", "aws-vpc": "10.20.0.0/16", "azure-vnet": "10.10.128.0/20", "gcp-vpc": "172.16.0.0/20"}
n = {k: ip.ip_network(v) for k, v in nets.items()}
keys = list(n)
for i, a in enumerate(keys):
    for b in keys[i + 1:]:
        if n[a].overlaps(n[b]):
            print(f"겹침: {a} {nets[a]} ↔ {b} {nets[b]}")
print("aws-vpc 를 /24 로 나누면", len(list(n["aws-vpc"].subnets(new_prefix=24))), "개, 한 칸 주소", n["aws-vpc"].subnets(new_prefix=24).__next__().num_addresses)
# 출력
# 겹침: onprem 10.10.0.0/16 ↔ azure-vnet 10.10.128.0/20
# aws-vpc 를 /24 로 나누면 256 개, 한 칸 주소 256
